fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    
    for &c in s.iter() {
        if c >= 'A' && c <= 'Z' {
            // Convert to lowercase by adding 32 to the ASCII value
            result.push((c as u8 + 32) as char);
        } else {
            // Keep the character unchanged
            result.push(c);
        }
    }
    
    result
}